import com.sap.gateway.ip.core.customdev.util.Message
Message processData(Message message) {
  try {
    def order = new XmlSlurper(false, false).parseText(message.getBody(String))
    def valid = order.name() == 'Order' && order.OrderID.text().trim() && order.Items.Item.size() > 0 && order.TotalAmount.text().toBigDecimal() > 0
    message.setProperty('validOrder', valid ? 'true' : 'false')
    message.setProperty('validationError', valid ? '' : 'OrderID, Items and positive TotalAmount are required')
  } catch (Exception e) {
    message.setProperty('validOrder', 'false')
    message.setProperty('validationError', 'Malformed order XML')
  }
  return message
}

import com.sap.gateway.ip.core.customdev.util.Message
import groovy.json.JsonSlurper
import groovy.json.JsonOutput
Message processData(Message message) {
 def order = new JsonSlurper().parseText(message.getBody(String))
 message.setHeader('Content-Type', 'application/json')
 message.setBody(JsonOutput.toJson([status:'accepted',order:order]))
 return message
}
